-- SQL Script to insert all leads into Supabase public.cnc_customers and public.cnc_enquiries

-- Allocation data is stored in the `remarks` column of cnc_enquiries


-- 1. Insert Customers
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  contact = EXCLUDED.contact,
  phone = EXCLUDED.phone,
  email = EXCLUDED.email,
  city = EXCLUDED.city,
  gst = EXCLUDED.gst;


-- 2. Insert Enquiries / Leads
ON CONFLICT DO NOTHING;
